//! Implementation of orbit behaviours for bases.

use anyhow::Context;
use derive_builder::Builder;

use crate::{
    analysis::{Orbit, OrbitIterator}, group::GroupProperties, symmetry::{
        symmetry_group::SymmetryGroupProperties,
        symmetry_transformation::{SymmetryTransformable, SymmetryTransformationKind},
    }, target::noci::basis::Basis,
};

// ==================
// BasisSymmetryOrbit
// ==================

// -----------------
// Struct definition
// -----------------

/// Structure to manage symmetry orbits (*i.e.* orbits generated by symmetry groups) of
/// bases.
#[derive(Builder, Clone)]
pub struct BasisSymmetryOrbit<'a, 'g, G, B>
where
    G: GroupProperties,
    B: Basis,
{
    /// The generating symmetry group.
    group: &'g G,

    /// The origin basis of the orbit.
    origin: &'a B,

    /// The kind of transformation determining the way the symmetry operations in `group` act on
    /// [`Self::origin`].
    symmetry_transformation_kind: SymmetryTransformationKind,
}

// ----------------------------
// Struct method implementation
// ----------------------------

impl<'a, 'g, G, B> BasisSymmetryOrbit<'a, 'g, G, B>
where
    G: GroupProperties + Clone,
    B: Basis + Clone,
{
    /// Returns a builder for constructing a new basis symmetry orbit.
    pub fn builder() -> BasisSymmetryOrbitBuilder<'a, 'g, G, B> {
        BasisSymmetryOrbitBuilder::default()
    }

    /// Returns the origin of the basis symmetry orbit.
    pub fn origin(&self) -> &B {
        self.origin
    }

    /// Returns the symmetry transformation kind.
    pub fn symmetry_transformation_kind(&self) -> &SymmetryTransformationKind {
        &self.symmetry_transformation_kind
    }
}

// ---------------------
// Trait implementations
// ---------------------

// ~~~~~
// Orbit
// ~~~~~

impl<'a, 'g, G, B> Orbit<G, B> for BasisSymmetryOrbit<'a, 'g, G, B>
where
    G: SymmetryGroupProperties,
    B: Basis + Clone + SymmetryTransformable,
{
    type OrbitIter = OrbitIterator<'a, G, B>;

    fn group(&self) -> &G {
        self.group
    }

    fn origin(&self) -> &B {
        self.origin
    }

    fn iter(&self) -> Self::OrbitIter {
        OrbitIterator::new(
            self.group,
            self.origin,
            match self.symmetry_transformation_kind {
                SymmetryTransformationKind::Spatial => |op, basis| {
                    basis.sym_transform_spatial(op).with_context(|| {
                        format!("Unable to apply `{op}` spatially on the origin basis")
                    })
                },
                SymmetryTransformationKind::SpatialWithSpinTimeReversal => |op, basis| {
                    basis.sym_transform_spatial_with_spintimerev(op).with_context(|| {
                        format!("Unable to apply `{op}` spatially (with spin-including time reversal) on the origin basis")
                    })
                },
                SymmetryTransformationKind::Spin => |op, basis| {
                    basis.sym_transform_spin(op).with_context(|| {
                        format!("Unable to apply `{op}` spin-wise on the origin basis")
                    })
                },
                SymmetryTransformationKind::SpinSpatial => |op, basis| {
                    basis.sym_transform_spin_spatial(op).with_context(|| {
                        format!("Unable to apply `{op}` spin-spatially on the origin basis")
                    })
                },
            },
        )
    }
}
